import math

CUBE = 0.040
BOWL_FOR = {"red": "cream", "green": "grey", "blue": "black"}
MAX_CALLS = 300


class _Budget(Exception):
    pass


class _Ctl:
    def __init__(self, api):
        self.api = api
        self.calls = 0
        self.pos = None  # last commanded pad position

    def _tick(self):
        if self.calls >= MAX_CALLS - 1:
            raise _Budget()
        self.calls += 1

    def cube(self, n=3):
        xs = ys = zs = s = c = 0.0
        votes = {}
        for _ in range(n):
            self._tick()
            (x, y, z), yaw, col = self.api.cube_pose()
            xs += x; ys += y; zs += z
            s += math.sin(math.radians(4.0 * yaw))
            c += math.cos(math.radians(4.0 * yaw))
            votes[col] = votes.get(col, 0) + 1
        yaw = math.degrees(math.atan2(s, c)) / 4.0
        col = max(votes, key=votes.get)
        return (xs / n, ys / n, zs / n), yaw, col

    def bowl(self, name, n=2):
        xs = ys = zs = 0.0
        for _ in range(n):
            self._tick()
            (x, y, z), _ = self.api.bowl_pose(name)
            xs += x; ys += y; zs += z
        return xs / n, ys / n, zs / n

    def move(self, xyz, yaw, step=0.10):
        """Move in short, roughly straight segments (joint-space moves bow otherwise)."""
        tgt = (float(xyz[0]), float(xyz[1]), float(xyz[2]))
        if self.pos is None:
            self._tick()
            self.api.move_to(tgt, yaw)
            self.pos = tgt
            return
        p = self.pos
        d = math.sqrt(sum((tgt[i] - p[i]) ** 2 for i in range(3)))
        n = max(1, int(math.ceil(d / step)))
        for k in range(1, n + 1):
            t = k / float(n)
            q = tuple(p[i] + (tgt[i] - p[i]) * t for i in range(3))
            self._tick()
            self.api.move_to(q, yaw)
            self.pos = q

    def suction(self, on):
        self._tick()
        return bool(self.api.suction(on))

    def done(self):
        self._tick()
        return bool(self.api.done())


def _attempt(c, bowls, travel_z):
    (cx, cy, cz), yaw, col = c.cube()
    bx, by, brim = bowls[BOWL_FOR.get(col, "grey")]

    # rise straight up first (if we know where we are), then go above the cube
    if c.pos is not None and c.pos[2] < travel_z - 1e-4:
        c.move((c.pos[0], c.pos[1], travel_z), yaw, step=0.05)
    c.move((cx, cy, travel_z), yaw, step=0.12)
    c.move((cx, cy, cz + 0.030), yaw, step=0.05)
    c.move((cx, cy, cz + 0.010), yaw, step=0.02)

    # gentle touch-down: creep onto the top face until the vacuum seals
    held = False
    for dz in (0.004, 0.002, 0.001, 0.0, -0.001, -0.002):
        c.move((cx, cy, cz + dz), yaw, step=0.02)
        if c.suction(True):
            held = True
            break
    if not held:
        c.suction(False)
        c.move((cx, cy, travel_z), yaw, step=0.05)
        return False

    # lift vertically, carry high over the rims, lower into the bowl, release
    c.move((cx, cy, cz + 0.02), yaw, step=0.02)
    c.move((cx, cy, travel_z), yaw, step=0.05)
    c.move((bx, by, travel_z), yaw, step=0.09)
    if not c.suction(True):          # lost the cube on the way
        c.suction(False)
        return False
    c.move((bx, by, brim + 0.005), yaw, step=0.035)
    c.suction(False)
    c.move((bx, by, travel_z), yaw, step=0.06)
    return c.done()


def run(api):
    c = _Ctl(api)
    try:
        if c.done():
            return
        bowls = {name: c.bowl(name) for name in ("cream", "grey", "black")}
        rim = max(b[2] for b in bowls.values())
        travel_z = rim + CUBE + 0.07   # held cube clears every rim by ~7 cm
        for _ in range(4):
            if MAX_CALLS - c.calls < 75:
                break
            if _attempt(c, bowls, travel_z):
                return
    except _Budget:
        try:
            api.suction(False)
        except Exception:
            pass
```

The policy reads the cube and bowl poses from the camera (averaged) rather than trusting the nominal positions, then moves in short interpolated segments at a height that keeps the held cube about 7 cm above every rim. It picks by creeping onto the top face in 1–2 mm steps with the vacuum on, stopping as soon as the cup seals, so the contact force stays low. It lowers the cube inside the matching bowl before releasing, checks `done()`, and re-senses and retries within the 300-call budget if anything failed.

